package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        // Lifted oracle from MannWhitneyUTestTest.testBigDataSet.
        double[] d1 = new double[1500];
        double[] d2 = new double[1500];
        for (int i = 0; i < 1500; i++) {
            d1[i] = 2 * i;
            d2[i] = 2 * i + 1;
        }
        Double liftedResult;
        try {
            liftedResult = testStatistic.mannWhitneyUTest(d1, d2);
        } catch (Throwable t) {
            return;
        }
        if (!(liftedResult > 0.1)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-big-dataset] semantic mismatch: expected result > 0.1 but got " + liftedResult);
        }

        // Contract justification: calculateAsymptoticPValue returns the two-sided asymptotic
        // p-value from the normal approximation. At Umin = n1*n2/2, z = 0, so any correct
        // implementation must return p = 2 * Phi(0) = 1.0. This directly constrains the
        // patched n1*n2 product computation and catches silent arithmetic corruption.
        int largeN1 = data.consumeInt(50000, 70000);
        int largeN2 = data.consumeInt(50000, 70000);
        Double midpointP;
        try {
            double uMin = ((double) largeN1 * (double) largeN2) / 2.0;
            java.lang.reflect.Method m =
                    MannWhitneyUTest.class.getDeclaredMethod("calculateAsymptoticPValue", double.class, int.class, int.class);
            m.setAccessible(true);
            midpointP = (Double) m.invoke(new MannWhitneyUTest(), uMin, largeN1, largeN2);
        } catch (Throwable t) {
            return;
        }
        double midpointTol = 1e-6 * Math.max(1.0, Math.abs(midpointP));
        if (!(Math.abs(midpointP - 1.0) <= midpointTol)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:midpoint-pvalue] metamorphic violation: expected midpoint asymptotic p-value 1.0 but got "
                            + midpointP + " for n1=" + largeN1 + ", n2=" + largeN2);
        }

        // Contract justification: swapping the two samples in a Mann-Whitney U test only
        // exchanges labels; the p-value must remain the same for every correct implementation.
        int n1 = data.consumeInt(1, 20);
        int n2 = data.consumeInt(1, 20);
        double[] x = new double[n1];
        double[] y = new double[n2];
        for (int i = 0; i < n1; i++) {
            x[i] = data.consumeInt(-1000, 1000);
        }
        for (int i = 0; i < n2; i++) {
            y[i] = data.consumeInt(-1000, 1000);
        }
        Double p1;
        Double p2;
        try {
            MannWhitneyUTest m = new MannWhitneyUTest();
            p1 = m.mannWhitneyUTest(x, y);
            p2 = m.mannWhitneyUTest(y, x);
        } catch (Throwable t) {
            return;
        }
        double swapTol = 1e-9 * Math.max(1.0, Math.max(Math.abs(p1), Math.abs(p2)));
        if (!(Math.abs(p1 - p2) <= swapTol)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:swap-symmetry] metamorphic violation: p(x,y)=" + p1 + " but p(y,x)=" + p2);
        }

        // Consistency cross-check: by definition of the Mann-Whitney statistic, U(x,y) +
        // U(y,x) = x.length * y.length. This compares the library's own outputs obtained via
        // two real API calls and catches silent arithmetic/bookkeeping errors.
        int n3 = data.consumeInt(1, 20);
        int n4 = data.consumeInt(1, 20);
        double[] a = new double[n3];
        double[] b = new double[n4];
        for (int i = 0; i < n3; i++) {
            a[i] = data.consumeInt(-1000, 1000);
        }
        for (int i = 0; i < n4; i++) {
            b[i] = data.consumeInt(-1000, 1000);
        }
        Double uab;
        Double uba;
        try {
            MannWhitneyUTest m = new MannWhitneyUTest();
            uab = m.mannWhitneyU(a, b);
            uba = m.mannWhitneyU(b, a);
        } catch (Throwable t) {
            return;
        }
        double expected = (double) n3 * (double) n4;
        double actual = uab + uba;
        double uTol = 1e-9 * Math.max(1.0, Math.max(Math.abs(actual), Math.abs(expected)));
        if (!(Math.abs(actual - expected) <= uTol)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:u-sum] consistency violation: U(x,y)+U(y,x)=" + actual + " but expected " + expected);
        }
    }
}

