package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import com.google.javascript.rhino.jstype.JSTypeRegistry;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String seedName = data.consumeBoolean() ? "x" : "arg";
        runOracle(
                "/** @param {number} " + seedName + " */\n"
                        + "function f(" + seedName + ") { /** @type {string} */ var " + seedName + " = ''; }",
                seedName,
                2,
                2);

        String first = data.consumeBoolean() ? "lead" : "a";
        String second = data.consumeBoolean() ? "x" : "q";
        runOracle(
                "/** @param {boolean} " + first + "\n"
                        + " * @param {number} " + second + " */\n"
                        + "function f(" + first + ", " + second + ") { /** @type {string} */ var " + second + " = ''; }",
                second,
                3,
                2);
    }

    private static void runOracle(String js, String conflictingName, int lineNumber, int expectedWarningCount) {
        Compiler compiler = new Compiler();
        Node n = compiler.parseTestCode(js);
        if (compiler.getErrorCount() != 0) {
            throw new RuntimeException("parse failed: " + compiler.getErrors()[0]);
        }

        Node externs = new Node(Token.BLOCK);
        Node externAndJsRoot = new Node(Token.BLOCK, externs, n);
        externAndJsRoot.setIsSyntheticBlock(true);

        new ProcessClosurePrimitives(compiler, CheckLevel.ERROR, true).process(null, n);

        CodingConvention convention = compiler.getCodingConvention();
        JSTypeRegistry registry = compiler.getTypeRegistry();
        new TypeCheck(
                compiler,
                new ClosureReverseAbstractInterpreter(convention, registry)
                        .append(new SemanticReverseAbstractInterpreter(convention, registry))
                        .getFirst(),
                registry)
                .processForTesting(null, n);

        if (compiler.getErrorCount() != 0) {
            throw new RuntimeException("unexpected errors after typecheck: " + compiler.getErrors()[0]);
        }

        JSError[] warnings = compiler.getWarnings();
        int warningCount = compiler.getWarningCount();
        if (warnings == null) {
            warnings = new JSError[0];
        }

        String expected0 =
                "variable " + conflictingName
                        + " redefined with type string, original definition at  [testcode] :"
                        + lineNumber + " with type number";
        String expected1 =
                "initializing variable\n"
                        + "found   : string\n"
                        + "required: number";

        if (warningCount != warnings.length) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:warning-array-consistency] semantic mismatch: warningCount="
                            + warningCount + " warnings.length=" + warnings.length);
        }

        if (warningCount != expectedWarningCount) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:duplicate-local-var-count] semantic mismatch: expected "
                            + expectedWarningCount + " warnings but got " + warningCount);
        }

        if (!normalize(expected0).equals(normalize(warnings[0].description))) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:duplicate-local-var-redef] semantic mismatch: expected="
                            + normalize(expected0) + " actual=" + normalize(warnings[0].description));
        }

        if (!normalize(expected1).equals(normalize(warnings[1].description))) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:duplicate-local-var-init] semantic mismatch: expected="
                            + normalize(expected1) + " actual=" + normalize(warnings[1].description));
        }

        Compiler compiler2 = new Compiler();
        Node n2 = compiler2.parseTestCode(js);
        if (compiler2.getErrorCount() != 0) {
            throw new RuntimeException("second parse failed: " + compiler2.getErrors()[0]);
        }
        new ProcessClosurePrimitives(compiler2, CheckLevel.ERROR, true).process(null, n2);
        CodingConvention convention2 = compiler2.getCodingConvention();
        JSTypeRegistry registry2 = compiler2.getTypeRegistry();
        new TypeCheck(
                compiler2,
                new ClosureReverseAbstractInterpreter(convention2, registry2)
                        .append(new SemanticReverseAbstractInterpreter(convention2, registry2))
                        .getFirst(),
                registry2)
                .processForTesting(null, n2);
        if (compiler2.getErrorCount() != 0) {
            throw new RuntimeException("unexpected errors after second typecheck: " + compiler2.getErrors()[0]);
        }
        JSError[] warnings2 = compiler2.getWarnings();
        if (warnings2 == null) {
            warnings2 = new JSError[0];
        }

        if (compiler2.getWarningCount() != warningCount || warnings2.length != warnings.length) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:fresh-compiler-agreement] semantic mismatch: firstCount="
                            + warningCount + " secondCount=" + compiler2.getWarningCount()
                            + " firstLen=" + warnings.length + " secondLen=" + warnings2.length);
        }
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }
}
